import { computed, unref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { resolveBackNavigation } from '../data/navigationOrigin.js'

export function useBackNavigation(fallbackTarget, fallbackLabel = 'Daftar') {
	const route = useRoute()
	const router = useRouter()
	const navigation = computed(() =>
		resolveBackNavigation(route, unref(fallbackTarget), unref(fallbackLabel)),
	)
	const backTarget = computed(() => navigation.value.target)
	const backLabel = computed(() => navigation.value.label)

	// Replace menghindari history menjadi List → Detail → List, yang membuat
	// tombol back perangkat membawa user kembali lagi ke Detail.
	function goBack() {
		return router.replace(backTarget.value)
	}

	return { backTarget, backLabel, goBack }
}
